SELECT
    _dlt_id as event_id
    {% for col in get_filtered_columns(from=source("ga4_select_star", "events"), except=["_dlt_id"])  %}
    , {{ col }} as {{ col }}
    {% endfor %}
FROM
    {{ source("ga4_select_star", "events") }}

{{
    config(
        materialized='table',
    )
}}

{% if should_full_refresh() %}
    -- take all loads when full refresh
    SELECT load_id, schema_name, schema_version_hash FROM {{ source('dlt_metadata', '_dlt_loads') }}
    -- TODO: the status value must be configurable so we can chain packages
    WHERE status = 0
{% else %}
    -- take only loads with status = 0 and no other records
    SELECT load_id, schema_name, schema_version_hash FROM {{ source('dlt_metadata', '_dlt_loads') }}
    GROUP BY load_id, schema_name, schema_version_hash
    -- note that it is a hack - we make sure no other statuses exist
    HAVING SUM(status) = 0
{% endif %}

{% macro get_filtered_columns(from, except=[]) %}

    {% set include_cols = [] %}
    {% set cols = adapter.get_columns_in_relation(from) %}
    {% set except = except | map("lower") | list %}
    {% for col in cols %}
        {% if col.column|lower not in except %}
            {% do include_cols.append(col.column) %}
        {% endif %}
    {% endfor %}

    {{ return(include_cols) }}

{% endmacro %}
